/**
 * Evaluation scenarios (TraceLens_Master_Plan.md Sec29): one entry per demo/buggy-app
 * bug, each backed by a real, deterministic video fixture generated by
 * scripts/generate-eval-fixtures.ts (not synthetic color bars).
 *
 * `failureTimestamp`/`toleranceSeconds` are estimated from the fixture-generation
 * script's known wait/action sequence (goto -> wait -> interact -> wait), not
 * verified frame-by-frame -- reasonable for a benchmark like this, but worth
 * being explicit that it's an estimate, not a hand-annotated ground truth.
 */
export interface EvalScenario {
  name: string;
  video: string;
  description: string;
  failureTimestamp: number;
  toleranceSeconds: number;
  expectedFiles: string[];
  rootCause: string;
}

export const EVAL_SCENARIOS: EvalScenario[] = [
  {
    name: "checkout-schema-mismatch",
    video: "checkout-schema-mismatch.mp4",
    description: "Clicking 'Place order' throws because data.orderId is undefined (the API returns `id`, not `orderId`).",
    failureTimestamp: 1.1,
    toleranceSeconds: 1.0,
    expectedFiles: ["demo/buggy-app/app/checkout/page.tsx"],
    rootCause: "Frontend reads data.orderId but the API returns { id, total } -- a response schema mismatch causes a TypeError.",
  },
  {
    name: "search-race-condition",
    video: "search-race-condition.mp4",
    description: "Typing 'cat' then quickly 'cats' shows stale 'cat' results because responses can arrive out of order.",
    failureTimestamp: 1.8,
    toleranceSeconds: 1.5,
    expectedFiles: ["demo/buggy-app/app/search/page.tsx"],
    rootCause: "No request-sequencing guard: a slower 'cat' response overwrites the newer, faster 'cats' response.",
  },
  {
    name: "responsive-regression",
    video: "responsive-regression.mp4",
    description: "At <=480px viewport width, the submit button is hidden underneath the fixed header.",
    failureTimestamp: 0.5,
    toleranceSeconds: 0.5,
    expectedFiles: ["demo/buggy-app/app/responsive/responsive.css"],
    rootCause: "The mobile media query grows the header's height without a matching increase to the content's padding-top.",
  },
];
